-- Transparent bevelled sprite alphabet for illustrated story captions.
-- Glyph positions and advances are generated by tools/build_story_lettering.py.
local Lettering={}
local data=require('src.story_lettering_data')
local image,quads
local function load()
    if image then return end
    image=love.graphics.newImage('assets/generated/story-intro/story-lettering-v1.png')
    image:setFilter('linear','linear')
    quads={}
    for code=32,126 do
        local index=code-32
        quads[code]=love.graphics.newQuad((index%data.columns)*data.cellW,
            math.floor(index/data.columns)*data.cellH,data.cellW,data.cellH,
            image:getWidth(),image:getHeight())
    end
end
function Lettering.measure(line,scale)
    local width=0
    for i=1,#line do
        local code=line:byte(i)
        width=width+(data.advances[code and code>=32 and code<=126 and code-31 or 1] or 17)
    end
    return width*(scale or 1)
end
function Lettering.wrap(message,scale,maxWidth)
    local lines={}
    local current=''
    for word in message:gmatch('%S+') do
        local candidate=current=='' and word or current..' '..word
        if current~='' and Lettering.measure(candidate,scale)>maxWidth then
            lines[#lines+1]=current
            current=word
        else current=candidate end
    end
    lines[#lines+1]=current
    return lines
end
function Lettering.drawLine(line,x,y,scale)
    load()
    love.graphics.setColor(1,1,1,1)
    for i=1,#line do
        local code=line:byte(i)
        local key=code>=32 and code<=126 and code or 63
        love.graphics.draw(image,quads[key],x,y,0,scale,scale)
        x=x+(data.advances[key-31] or 17)*scale
    end
end
function Lettering.draw(message,x,y,width,scale,alignment)
    local lines=Lettering.wrap(message,scale,width)
    local lineHeight=75*scale
    for i,line in ipairs(lines) do
        local lineWidth=Lettering.measure(line,scale)
        local px=alignment=='center' and x+(width-lineWidth)*.5
            or alignment=='right' and x+width-lineWidth or x
        Lettering.drawLine(line,px,y+(i-1)*lineHeight,scale)
    end
    return #lines*lineHeight
end
return Lettering
